<script lang="ts">
 import {Paperclip,Eye,Download,Trash2} from '@lucide/svelte';
 import {exportFileCanPreview,type InvoiceFile} from './exportDocumentation';
 import type {Row} from './types';
 let {label,inputID,files,queued,canAttach,canRemove,canDownload,busy,uncertain,compact=false,onattach,onremove,onremovequeued}:{compact?:boolean;label:string;inputID:string;files:Row[];queued:InvoiceFile[];canAttach:boolean;canRemove:boolean;canDownload:boolean;busy:boolean;uncertain:boolean;onattach:(event:Event)=>void;onremove:(file:Row)=>void;onremovequeued:(key:string)=>void}=$props();
</script>
<div class="document-field" class:compact>
 <div class="document-heading"><strong>{label}</strong>{#if canAttach}<label class="document-button attach"><Paperclip size={14}/>Attach<input id={inputID} type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.docx,.xlsx" aria-label={'Attach '+label} disabled={busy} onchange={onattach}/></label>{/if}</div>
 <ul>{#each files as file}<li><span><strong>{file.filename}</strong><small>{Math.max(1,Math.round(file.size/1024))} KB</small></span><div class="document-actions">{#if canDownload}{#if exportFileCanPreview(file)}<a class="document-button" href={'/api/export-files/'+file.id+'?preview=1'} target="_blank" rel="noopener noreferrer" data-sveltekit-reload data-sveltekit-preload-data="false" aria-label={'Preview '+file.filename}><Eye size={14}/>Preview</a>{/if}<a class="document-button" href={'/api/export-files/'+file.id+'?download=1'} download data-sveltekit-reload data-sveltekit-preload-data="false" aria-label={'Download '+file.filename}><Download size={14}/>Download</a>{/if}{#if canRemove}<button type="button" class="document-button" disabled={busy||uncertain} aria-label={'Remove '+file.filename} onclick={()=>onremove(file)}><Trash2 size={14}/>Remove</button>{/if}</div></li>{/each}
 {#each queued.filter(item=>!files.some(file=>file.id===item.id)) as item(item.key)}<li><span><strong>{item.file.name}</strong><small>{item.status==='uploaded'?'Attached':item.status==='uncertain'?'Upload unconfirmed':item.status==='uploading'?'Uploading…':item.status==='failed'?'Upload failed':'Queued · save to attach'}</small>{#if item.error}<small class="error">{item.error}</small>{/if}</span>{#if !item.path&&item.status!=='uploaded'}<button type="button" class="document-button" disabled={busy} aria-label={'Remove queued '+item.file.name} onclick={()=>onremovequeued(item.key)}><Trash2 size={14}/>Remove</button>{/if}</li>{/each}</ul>
 {#if !files.length&&!queued.length}<small>No document attached.</small>{/if}
</div>
<style>
 @media(min-width:1024px){
 .document-field{min-width:0;padding:12px 0;border-top:1px solid var(--ex-line);margin-top:14px}.document-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.document-heading>strong{font-size:12px;line-height:1.5}.document-button{display:inline-flex;align-items:center;justify-content:center;gap:5px;border:1px solid transparent;background:none;color:var(--ex-teal);font-family:inherit;font-size:12px;font-weight:700;padding:6px;min-height:32px;border-radius:6px;cursor:pointer;text-decoration:none;white-space:nowrap}.document-button:hover{background:#e9f3ef}.document-button.attach{position:relative;overflow:hidden;background:#edf4f5;border-color:#bfced3;color:#183f50;padding:6px 9px}.attach input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.document-button:disabled{cursor:not-allowed;opacity:.6}.document-button:focus-visible,.attach:focus-within{outline:3px solid #58a9a1;outline-offset:3px}ul{list-style:none;margin:5px 0 0;padding:0}li{display:flex;flex-wrap:wrap;gap:6px 12px;align-items:center;justify-content:space-between;padding:7px 0;font-size:12px;line-height:1.5}li>span{min-width:0;overflow-wrap:anywhere;flex:1 1 180px}small{display:block;font-size:11px;line-height:1.5;color:var(--ex-muted);font-weight:400;margin-top:4px}.document-actions{display:flex;align-items:center;gap:2px;flex-wrap:wrap}.error{color:#8e2c27}
 .document-field.compact{margin-top:0;padding:0;border-top:0}.compact .document-heading{gap:8px;min-height:26px;align-items:center}.compact .document-heading>strong{font-size:12px;line-height:1.4}.compact .document-button{min-height:30px;padding:4px 5px;font-size:12px;gap:4px}.compact .document-button.attach{padding:4px 7px;flex-shrink:0}.compact ul{margin:2px 0 0}.compact li{gap:2px 8px;padding:3px 0;align-items:center}.compact li>span{display:flex;flex-wrap:wrap;align-items:baseline;gap:1px 7px;flex:1 1 145px}.compact li>span>strong{font-size:12px;line-height:1.4;overflow-wrap:anywhere}.compact li>span>small{margin:0;font-size:11px;white-space:nowrap}.compact li>span>small.error{white-space:normal;flex-basis:100%}.compact .document-actions{gap:0}.compact>small{font-size:11px;margin-top:2px}
 }
</style>
